package work.starlings.android.keep

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * `resources/keep/vectors.json` is a copy of `envisioning/keep`
 * `packages/crypto/src/vectors.json` (by way of core-kit
 * `Tests/KeepKitTests/Fixtures`), generated by the TypeScript
 * implementation. Everything in it must open here with the keys given.
 * Mirrors core-kit `KeepCryptoTests.swift`. Regenerate there, copy here.
 */
class KeepCryptoTest {
    @Serializable
    data class Key(@SerialName("public_key") val publicKey: String, @SerialName("private_key_pkcs8") val privateKeyPkcs8: String)

    @Serializable
    data class Vault(val id: String, val key: String, @SerialName("key_version") val keyVersion: Int, @SerialName("wrapped_to_recipient") val wrappedToRecipient: KeepWrappedKey)

    @Serializable
    data class Item(val id: String, val body: KeepItemBody, val sealed: KeepSealed)

    @Serializable
    data class Wrapped(val value: String? = null, val output: String? = null, val wrapped: KeepSealed, val wrap: KeepWrapParams)

    @Serializable
    data class Vectors(val suite: String, val staff: Key, val recipient: Key, val vault: Vault, val item: Item, val passphrase: Wrapped, val prf: Wrapped)

    private val v: Vectors by lazy {
        val text = javaClass.classLoader!!.getResource("keep/vectors.json")!!.readText()
        KeepJson.decodeFromString(Vectors.serializer(), text)
    }

    @Test
    fun opensItemSealedByTypeScript() {
        assertEquals(KeepSuite.CURRENT, v.suite)
        val key = KeepCrypto.vaultKey(KeepCrypto.data(v.vault.key))
        val body = KeepCrypto.openItem(v.item.sealed, key, v.vault.id, v.item.id, v.vault.keyVersion)
        assertEquals(v.item.body, body)
        assertEquals("line one\nline two — ünïcödé", body.notes)
        assertThrows(KeepCryptoError::class.java) { KeepCrypto.openItem(v.item.sealed, key, v.vault.id, v.item.id, v.vault.keyVersion + 1) }
    }

    @Test
    fun unwrapsVaultKeyWrappedByTypeScript() {
        val recipient = KeepCrypto.importPrivateKey(KeepCrypto.data(v.recipient.privateKeyPkcs8))
        assertEquals(v.recipient.publicKey, recipient.publicKey)
        val key = KeepCrypto.unwrapKey(v.vault.wrappedToRecipient, recipient, v.recipient.publicKey)
        assertEquals(v.vault.key, KeepCrypto.base64URL(key))
        // Re-addressed to the staff key: AAD mismatch.
        assertThrows(KeepCryptoError::class.java) { KeepCrypto.unwrapKey(v.vault.wrappedToRecipient, recipient, v.staff.publicKey) }
    }

    @Test
    fun unwrapsPrivateKeyWrappedByPassphrase() {
        val wrap = v.passphrase.wrap
        assertEquals(KeepWrapParams.PASSPHRASE, wrap.method)
        val salt = KeepCrypto.data(wrap.pbkdf2Salt!!)
        val wrappingKey = KeepCrypto.wrappingKey(v.passphrase.value!!, salt, wrap.pbkdf2Iterations!!)
        val restored = KeepCrypto.unwrapPrivateKey(v.passphrase.wrapped, wrappingKey)
        assertEquals(v.staff.publicKey, restored.publicKey)
        val wrong = KeepCrypto.wrappingKey("not it", salt, wrap.pbkdf2Iterations!!)
        assertThrows(KeepCryptoError::class.java) { KeepCrypto.unwrapPrivateKey(v.passphrase.wrapped, wrong) }
        // The server's floor holds here too.
        assertThrows(KeepCryptoError::class.java) { KeepCrypto.wrappingKey(v.passphrase.value!!, salt, 1000) }
    }

    @Test
    fun unwrapsPrivateKeyWrappedByPRF() {
        val wrap = v.prf.wrap
        assertTrue(wrap.isPasskey)
        val wrappingKey = KeepCrypto.wrappingKey(KeepCrypto.data(v.prf.output!!), KeepCrypto.data(wrap.hkdfSalt!!))
        val restored = KeepCrypto.unwrapPrivateKey(v.prf.wrapped, wrappingKey)
        assertEquals(v.staff.publicKey, restored.publicKey)
    }

    /** Both vector keys import, and export back to the same PKCS#8 bytes WebCrypto wrote. */
    @Test
    fun importsAndExportsPKCS8ByteForByte() {
        for (key in listOf(v.staff, v.recipient)) {
            val der = KeepCrypto.data(key.privateKeyPkcs8)
            val imported = KeepCrypto.importPrivateKey(der)
            assertEquals(key.publicKey, imported.publicKey)
            assertArrayEquals(der, KeepCrypto.exportPrivateKey(imported))
        }
    }

    /**
     * What this side seals, the other side must open, so the exported
     * private key has to be PKCS#8 (what WebCrypto imports), not SEC1.
     */
    @Test
    fun exportsPKCS8() {
        val pair = KeepCrypto.generateStaffKeypair()
        val der = KeepCrypto.exportPrivateKey(pair)
        assertEquals(138, der.size)
        assertArrayEquals(byteArrayOf(0x30, 0x81.toByte(), 0x87.toByte(), 0x02, 0x01, 0x00, 0x30, 0x13, 0x06, 0x07), der.copyOf(10))
        assertEquals(pair.publicKey, KeepCrypto.importPrivateKey(der).publicKey)
    }

    @Test
    fun roundTripsEverythingItSeals() {
        val alice = KeepCrypto.generateStaffKeypair()
        val vaultKeyBytes = KeepCrypto.generateVaultKey()
        val wrapped = KeepCrypto.wrapKey(vaultKeyBytes, alice.publicKey)
        assertArrayEquals(vaultKeyBytes, KeepCrypto.unwrapKey(wrapped, alice, alice.publicKey))

        val key = KeepCrypto.vaultKey(vaultKeyBytes)
        val body = KeepItemBody(username = "u", password = "p", url = "https://x", notes = "n", totp = "")
        val sealed = KeepCrypto.sealItem(body, key, "v", "i", 1)
        assertEquals(body, KeepCrypto.openItem(sealed, key, "v", "i", 1))
        assertThrows(KeepCryptoError::class.java) { KeepCrypto.openItem(sealed, key, "w", "i", 1) }

        val (wrappedKey, wrap) = KeepCrypto.wrapPrivateKey(alice, "correct horse battery staple")
        assertEquals(KeepSuite.PBKDF2_ITERATIONS, wrap.pbkdf2Iterations)
        val wrappingKey = KeepCrypto.wrappingKey("correct horse battery staple", KeepCrypto.data(wrap.pbkdf2Salt!!), wrap.pbkdf2Iterations!!)
        assertEquals(alice.publicKey, KeepCrypto.unwrapPrivateKey(wrappedKey, wrappingKey).publicKey)

        val prf = KeepCrypto.randomBytes(32)
        val (prfWrapped, prfWrap) = KeepCrypto.wrapPrivateKey(alice, prf, "cred")
        assertEquals("cred", prfWrap.credentialId)
        val prfKey = KeepCrypto.wrappingKey(prf, KeepCrypto.data(prfWrap.hkdfSalt!!))
        assertEquals(alice.publicKey, KeepCrypto.unwrapPrivateKey(prfWrapped, prfKey).publicKey)
    }

    /** A passphrase in another Unicode form opens the same wrap: both sides take NFKC. */
    @Test
    fun passphraseIsNormalised() {
        val salt = KeepCrypto.randomBytes(32)
        val composed = KeepCrypto.wrappingKey("café ﬁ", salt, KeepSuite.PBKDF2_ITERATIONS)
        val decomposed = KeepCrypto.wrappingKey("café fi", salt, KeepSuite.PBKDF2_ITERATIONS)
        assertArrayEquals(composed.bytes, decomposed.bytes)
    }

    /** RFC 6070-style check of the hand-rolled PBKDF2 against the JCA's, for ASCII where they agree. */
    @Test
    fun pbkdf2MatchesThePlatform() {
        val salt = "salt".toByteArray()
        val factory = javax.crypto.SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256")
        val spec = javax.crypto.spec.PBEKeySpec("password".toCharArray(), salt, 4096, 256)
        assertArrayEquals(factory.generateSecret(spec).encoded, KeepCrypto.pbkdf2("password".toByteArray(), salt, 4096))
    }

    /** RFC 5869 test case 1. */
    @Test
    fun hkdfMatchesRFC5869() {
        fun hex(s: String) = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
        val okm = KeepCrypto.hkdf(hex("0b".repeat(22)), hex("000102030405060708090a0b0c"), hex("f0f1f2f3f4f5f6f7f8f9"), 32)
        assertArrayEquals(hex("3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf"), okm)
    }

    @Test
    fun releaseRoundTrips() {
        val session = KeepCrypto.generateStaffKeypair()
        val body = KeepItemBody(username = "u", password = "p")
        val (sealed, wrapped) = KeepCrypto.sealRelease(body, session.publicKey, "r1", "v1", "i1")
        assertEquals(body, KeepCrypto.openRelease(sealed, wrapped, session, session.publicKey, "r1", "v1", "i1"))
        assertThrows(KeepCryptoError::class.java) { KeepCrypto.openRelease(sealed, wrapped, session, session.publicKey, "r2", "v1", "i1") }
    }

    @Test
    fun wireShapesMatchTheContract() {
        val wrap = KeepJson.encodeToString(KeepWrapParams.serializer(), KeepWrapParams.prf("c", "s"))
        assertTrue(wrap, wrap.contains("\"method\":\"prf\""))
        assertTrue(wrap, wrap.contains("\"credential_id\":\"c\""))
        assertTrue(wrap, wrap.contains("\"hkdf_salt\":\"s\""))
        assertFalse(wrap, wrap.contains("pbkdf2"))
        val created = KeepJson.encodeToString(KeepCreateVaultInput.serializer(), KeepCreateVaultInput(name = "A", projectId = null, members = emptyList(), recoveryWrappedKey = null))
        assertTrue(created, created.contains("\"recovery_wrapped_key\":null"))
        assertTrue(created, created.contains("\"project_id\":null"))
        assertFalse(created, created.contains("icon"))
        val update = KeepJson.encodeToString(KeepUpdateItemInput.serializer(), KeepUpdateItemInput(name = "n"))
        assertEquals("{\"name\":\"n\"}", update)
        val vault = KeepJson.encodeToString(KeepUpdateVaultInput.serializer(), KeepUpdateVaultInput("n", null, null))
        assertEquals("{\"name\":\"n\",\"icon\":null,\"project_id\":null}", vault)
        // Every body field is written, in the contract's order, even when empty.
        assertEquals(
            "{\"username\":\"\",\"password\":\"\",\"url\":\"\",\"notes\":\"\",\"totp\":\"\"}",
            KeepJson.encodeToString(KeepItemBody.serializer(), KeepItemBody()),
        )
        // A body sealed by an older client, with fields missing, still opens.
        assertEquals(KeepItemBody(password = "p"), KeepJson.decodeFromString(KeepItemBody.serializer(), "{\"password\":\"p\"}"))
    }

    @Test
    fun keysAndBodiesNeverPrintTheirValue() {
        val pair = KeepCrypto.generateStaffKeypair()
        assertFalse(pair.toString().contains(pair.publicKey))
        assertFalse(KeepItemBody(password = "hunter2").toString().contains("hunter2"))
    }
}

/** Shares must round-trip, and match the web's `keep-recovery-A:…` format. */
class KeepRecoveryShareTest {
    @Test
    fun splitJoinAndFormat() {
        val pair = KeepCrypto.generateStaffKeypair()
        val secret = KeepCrypto.exportPrivateKey(pair)
        val (a, b) = KeepCrypto.splitSecret(secret)
        assertArrayEquals(secret, KeepCrypto.joinShares(a, b))
        assertFalse(KeepCrypto.joinShares(a, a).contentEquals(secret))
        val textA = KeepCrypto.formatShare("A", a)
        val textB = KeepCrypto.formatShare("B", b)
        assertTrue(textA.startsWith("keep-recovery-A:"))
        val parsedA = KeepCrypto.parseShare(" $textA\n")
        val parsedB = KeepCrypto.parseShare(textB)
        val restored = KeepCrypto.importPrivateKey(KeepCrypto.joinShares(parsedA.second, parsedB.second))
        assertEquals(pair.publicKey, restored.publicKey)
        assertThrows(KeepCryptoError::class.java) { KeepCrypto.parseShare("keep-recovery-C:AAAA") }
        assertThrows(KeepCryptoError::class.java) { KeepCrypto.parseShare("nope") }
    }
}

class KeepGeneratorTest {
    @Test
    fun presetsHoldTheirShape() {
        repeat(50) {
            val strong = KeepPasswordGenerator.generate(KeepPasswordOptions.strong)
            assertEquals(20, strong.length)
            assertTrue(strong.any { it.isUpperCase() } && strong.any { it.isDigit() } && strong.any { it in "!#$%&*+-=?@^_~" })
            assertTrue(strong.none { it in "0Oo1lI|" })
            val pin = KeepPasswordGenerator.generate(KeepPasswordOptions.pin)
            assertTrue(pin.length == 6 && pin.all { it.isDigit() })
            val readable = KeepPasswordGenerator.generate(KeepPasswordOptions.readable)
            assertTrue(readable, Regex("^[a-z2-9]{4}(-[a-z2-9]{4}){4}$").matches(readable))
            assertTrue(KeepPasswordGenerator.generate(KeepPasswordOptions.alphanumeric).all { it.isLetterOrDigit() })
            assertEquals(32, KeepPasswordGenerator.generate(KeepPasswordOptions.long).length)
        }
        assertEquals(listOf("strong", "long", "alnum", "readable", "pin"), KeepPasswordPreset.all.map { it.id })
    }

    @Test
    fun passphraseIsFiveGroupsOfFour() {
        val a = KeepPassphrase.generate()
        assertTrue(a, Regex("^[a-hj-km-np-z2-9]{4}(-[a-hj-km-np-z2-9]{4}){4}$").matches(a))
        assertNotEquals(a, KeepPassphrase.generate())
    }
}
